const required = ['vehicle_id', 'timestamp', 'coordinates', 'speed', 'battery_percentage'];
const payload = msg.payload;
const missing = required.filter(k => payload[k] === undefined || payload[k] === null);
if (missing.length > 0) {
    node.warn(`Rejected malformed payload from ${payload.vehicle_id || 'unknown'}: missing ${missing.join(',')}`);
    return null;
}
return msg;

const ctx = context.get('lastByVehicle') || {};
const v = msg.payload.vehicle_id;
const prev = ctx[v];
if (msg.payload.speed === 0 && prev && prev.speed === 0) {
    ctx[v] = msg.payload; context.set('lastByVehicle', ctx); return null;
}
if (prev && Math.abs(prev.battery_percentage - msg.payload.battery_percentage) < 0.5 && prev.speed === msg.payload.speed) {
    ctx[v] = msg.payload; context.set('lastByVehicle', ctx); return null;
}
ctx[v] = msg.payload; context.set('lastByVehicle', ctx); return msg;

const { lat, lng } = msg.payload.coordinates;
msg.payload.location = { type: 'Point', coordinates: [lng, lat] };
return msg;

const v = msg.payload.vehicle_id;
const windows = context.get('speedWindows') || {};
const w = windows[v] || [];
w.push(msg.payload.speed);
if (w.length > 10) w.shift();
windows[v] = w;
context.set('speedWindows', windows);
const avg = w.reduce((a, b) => a + b, 0) / w.length;
msg.payload.avg_speed_rolling = Number(avg.toFixed(1));
return msg;

const { lat, lng } = msg.payload.coordinates;
const zoneLat = Math.floor(lat * 1000);
const zoneLng = Math.floor(lng * 1000);
const zoneId = `zone_${zoneLat}_${zoneLng}`;
msg.payload.zone_id = zoneId;
const zoneCounts = context.get('zoneCounts') || {};
zoneCounts[zoneId] = (zoneCounts[zoneId] || 0) + 1;
context.set('zoneCounts', zoneCounts);
msg.payload.zone_vehicle_count = zoneCounts[zoneId];
return msg;

msg.payload.status_flags = msg.payload.status_flags || [];
if (msg.payload.proximity_warning && msg.payload.speed < 5 && !msg.payload.status_flags.includes('SUSPECTED_CRASH')) {
    msg.payload.status_flags.push('SUSPECTED_CRASH');
}
return msg;

const [SQSClient, SendMessageCommand] = global.get(['SQSClient','SendMessageCommand']);
const queueUrls = global.get('queueUrls');
const region = global.get('awsRegion');

let category = 'geofencing';
if ((msg.payload.status_flags || []).length > 0) {
    category = 'alerting';
} else if (msg.payload.ride_id !== undefined && msg.payload.ride_id !== null) {
    category = 'dispatch';
}

let client = context.get('sqsClient'); if (client === undefined) { client = new SQSClient({ region }); context.set('sqsClient', client); }
client.send(new SendMessageCommand({
    QueueUrl: queueUrls[category],
    MessageBody: JSON.stringify(msg.payload),
})).then(() => {
    msg.routed_to = category;
    node.send(msg);
    node.done();
}).catch((err) => {
    node.error(`SQS publish failed (${category}): ${err.message}`, msg);
    node.done();
});
return;
